package com.acme.billing.service;

import com.acme.billing.api.BillingDtos.CancelledInvoiceResponse;
import com.acme.billing.domain.Invoice;
import com.acme.billing.domain.InvoiceRepository;
import com.acme.billing.domain.InvoiceStatus;
import com.acme.billing.error.InvoiceNotCancellableException;
import com.acme.billing.error.InvoiceNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InvoiceService {

    private final InvoiceRepository invoiceRepository;

    public InvoiceService(InvoiceRepository invoiceRepository) {
        this.invoiceRepository = invoiceRepository;
    }

    @Transactional
    public CancelledInvoiceResponse cancelInvoice(long customerId, long invoiceId) {
        Invoice invoice = invoiceRepository.findById(invoiceId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));

        if (invoice.customerId() != customerId) {
            // Same exception as "not found" so we don't leak the existence of
            // another customer's invoice to an unauthorized caller.
            throw new InvoiceNotFoundException(invoiceId);
        }

        if (invoice.status() != InvoiceStatus.UNPAID) {
            throw new InvoiceNotCancellableException(invoiceId, invoice.status());
        }

        invoice.markCancelled();
        return new CancelledInvoiceResponse(invoiceId, invoice.status());
    }
}
